const input = $json.body ?? $json;
const b = input && typeof input === 'object' ? input : {};
function lit(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return `'${String(value).replaceAll("'", "''")}'`;
}
const providerMessageId = b.provider_message_id || b.message_id || b.data?.message_id || b.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.id || null;
const providerEventId = b.provider_event_id || b.event_id || b.id || null;
const status = String(b.provider_status || b.status || b.event_type || b.event || b.data?.status || '').toLowerCase();
const channelId = b.channel_id || b.data?.channel_id || null;
const phoneNumberId = b.phone_number_id || b.metadata?.phone_number_id || b.entry?.[0]?.changes?.[0]?.value?.metadata?.phone_number_id || null;
const channelType = b.channel_type || b.channel || b.data?.channel || null;
const tenantIdentifier = b.tenant_identifier || b.instance_id || b.data?.instance_id || null;
const metadata = JSON.stringify({source: 'notifications.v2.delivery_webhook', payload: b});
let statusQuery;
if (!providerMessageId || !status) {
  statusQuery = "SELECT 'IGNORED_INVALID_DELIVERY_EVENT' AS result;";
} else {
  statusQuery = `WITH c AS (\n  SELECT id FROM public.channels\n  WHERE deleted_at IS NULL\n    AND (\n      id = ${lit(channelId)}::uuid\n      OR phone_number_id = ${lit(phoneNumberId)}\n      OR (lower(type) = lower(${lit(channelType)}) AND (config->>'thikaa_instance_id') = ${lit(tenantIdentifier)})\n    )\n  ORDER BY CASE WHEN id = ${lit(channelId)}::uuid THEN 1 WHEN phone_number_id = ${lit(phoneNumberId)} THEN 2 ELSE 3 END, id\n  LIMIT 1\n)\nSELECT public.notification_apply_channel_status(c.id, ${lit(providerMessageId)}, ${lit(providerEventId)}, ${lit(status)}, NULL, '${metadata.replaceAll("'", "''")}'::jsonb) AS result\nFROM c;`;
}
return [{json: {provider_message_id: providerMessageId, provider_status: status, status_query: statusQuery}}];
